#!/usr/bin/env python3
"""S19 test-runner helper: parse tool output, judge expectations, assemble JSON."""
import json
import os
import re
import shutil
import subprocess
import sys
import datetime


def read_lines(path):
    try:
        with open(path, "r", errors="replace") as fh:
            return fh.read().splitlines()
    except FileNotFoundError:
        return []


def parse_line(raw):
    """Return dict(status, verdict, receipt, evidence, nfields, raw, fmt)."""
    fields = raw.split("\t")
    n = len(fields)
    fmt = None
    path = verdict = receipt = evidence = None
    if n >= 4 and fields[0] == "VERDICT":
        fmt = "VERDICT"
        path = fields[1]
        verdict = fields[2]
        if n >= 4:
            receipt = fields[3]
        if n >= 5:
            evidence = "\t".join(fields[4:])
    elif n >= 4:
        fmt = "bare"
        path, verdict, receipt = fields[0], fields[1], fields[2]
        evidence = "\t".join(fields[3:])
    else:
        return None
    verdict = verdict.strip()
    receipt = (receipt or "").strip()
    m = re.match(r"^(SAFE|NOT-SAFE)\s*\((.*)\)$", verdict)
    if m:
        verdict = m.group(1)
        inner = m.group(2).strip()
        if not receipt or receipt in ("-", ""):
            receipt = inner
    receipt = receipt.strip().strip("()")
    return {
        "fmt": fmt, "path": path, "verdict": verdict, "receipt": receipt,
        "evidence": (evidence or "").strip(), "nfields": n, "raw": raw,
    }


def match_path(candidate, target):
    if candidate == target:
        return True
    if os.path.normpath(candidate) == os.path.normpath(target):
        return True
    if os.path.basename(candidate.rstrip("/")) == os.path.basename(target.rstrip("/")):
        return True
    return False


def cmd_line(args):
    outfile, target = args[0], args[1]
    hits = []
    for raw in read_lines(outfile):
        p = parse_line(raw)
        if not p or not p["path"]:
            continue
        if match_path(p["path"], target):
            hits.append(p)
    if not hits:
        print("missing\t\t\t\t0\t")
        return
    exact = [h for h in hits if h["path"] == target or os.path.normpath(h["path"]) == os.path.normpath(target)]
    if len(exact) == 1:
        h = exact[0]
    elif len(hits) == 1:
        h = hits[0]
    else:
        print(f"ambiguous\t\t\t\t{len(hits)}\t" + " | ".join(h["raw"] for h in hits[:3]))
        return
    print("\t".join(["found", h["verdict"], h["receipt"], h["evidence"],
                     str(h["nfields"]), h["raw"]]))


def load_expected(path):
    with open(path) as fh:
        return json.load(fh)


def expected_entry(exp, target):
    for t in exp.get("targets", []):
        p = t.get("path", "")
        if p == target or os.path.basename(p) == os.path.basename(target):
            return t
    return None


def cmd_targets(args):
    exp = load_expected(args[0])
    for t in exp.get("targets", []):
        if t.get("path"):
            print(t["path"])


def cmd_exitcode(args):
    exp = load_expected(args[0])
    if "run_exit_code" in exp:
        print(exp["run_exit_code"])


def cmd_canaries(args):
    exp = load_expected(args[0])
    c = exp.get("leak_canaries")
    if isinstance(c, dict):
        for v in c.values():
            if v:
                print(v)
    elif isinstance(c, list):
        for v in c:
            print(v)


def observed_parts(observed_tsv):
    fields = observed_tsv.split("\t")
    if len(fields) >= 4 and fields[0] in ("found", "ambiguous", "missing"):
        status = fields[0]
        verdict = fields[1] if len(fields) > 1 else ""
        receipt = fields[2] if len(fields) > 2 else ""
        evidence = fields[3] if len(fields) > 3 else ""
        return status, verdict, receipt, evidence
    # bare verdict string fallback
    return ("found" if observed_tsv.strip() else "missing", observed_tsv.strip(), "", "")


def cmd_judge(args):
    observed = ""
    expected_file = None
    target = None
    verdict_set = None
    receipt_set = None
    evidence_regex = None
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--observed":
            observed = args[i + 1]; i += 2
        elif a == "--expected-file":
            expected_file = args[i + 1]; i += 2
        elif a == "--target":
            target = args[i + 1]; i += 2
        elif a == "--verdict-set":
            verdict_set = args[i + 1].split(","); i += 2
        elif a == "--receipt-set":
            receipt_set = args[i + 1].split(","); i += 2
        elif a == "--evidence-regex":
            evidence_regex = args[i + 1]; i += 2
        else:
            i += 1

    status, verdict, receipt, evidence = observed_parts(observed)
    exp_desc = ""
    problems = []
    if expected_file:
        exp = load_expected(expected_file)
        entry = expected_entry(exp, target)
        if entry is None:
            print("NOT-EXERCISED\tschema:target-not-found\tno expected entry for target")
            return
        spec = entry.get("expected", {})
        vs = spec.get("verdict_set") or ([spec["verdict"]] if "verdict" in spec else None)
        rs = spec.get("receipt_set") or ([spec["receipt"]] if "receipt" in spec else None)
        forbidden = spec.get("forbidden_receipt")
        exp_desc = f"verdict={'|'.join(vs) if vs else '*'} receipt={'|'.join(rs) if rs else '*'}"
        if vs is None:
            exp_desc = "schema:no-expected-spec"
            problems.append("expected entry carries no verdict spec")
        else:
            if status != "found":
                problems.append(f"no verdict line matched ({status})")
            else:
                if verdict not in vs:
                    problems.append(f"verdict {verdict} not in {vs}")
                if rs and receipt not in rs:
                    problems.append(f"receipt {receipt!r} not in {rs}")
                if forbidden and receipt == forbidden:
                    problems.append(f"receipt {receipt!r} is forbidden")
        if spec.get("evidence_regex") and status == "found" and not re.search(spec["evidence_regex"], evidence):
            problems.append("evidence regex not matched")
    else:
        exp_desc = f"verdict={'|'.join(verdict_set) if verdict_set else '*'} receipt={'|'.join(receipt_set) if receipt_set else '*'}"
        if evidence_regex:
            exp_desc += f" evidence~/{evidence_regex}/"
        if status != "found":
            problems.append(f"no verdict line matched ({status})")
        else:
            if verdict_set and verdict not in verdict_set:
                problems.append(f"verdict {verdict!r} not in {verdict_set}")
            if receipt_set and receipt not in receipt_set:
                problems.append(f"receipt {receipt!r} not in {receipt_set}")
            if evidence_regex and not re.search(evidence_regex, evidence):
                problems.append(f"evidence {evidence!r} !~ /{evidence_regex}/")
    if problems:
        print("FAIL\t" + exp_desc + "\t" + "; ".join(problems))
    else:
        print("PASS\t" + exp_desc + "\tobserved " + f"{verdict}/{receipt}")


def cmd_verdict(args):
    rows = [r.split("\t") for r in read_lines(args[0]) if r.strip()]
    statuses = [r[0] for r in rows if r]
    if "TOOL-ABSENT" in statuses:
        print("TOOL-ABSENT")
    elif "FAIL" in statuses:
        print("FAIL")
    else:
        print("PASS")


