SPEC_FALLBACK = {
    "F1": {"verdict": "SAFE", "receipt": "pushed"},
    "F2": {"verdict": "NOT-SAFE", "receipt_set": ["none", "pushed-unverifiable"]},
    "F3": {"verdict": "NOT-SAFE", "evidence_regex": r"unpushed=2"},
    "F4": {"verdict": "SAFE", "receipt": "metadata-prune"},
    "F5": {"verdict": "NOT-SAFE", "receipt": "unpushed-branch"},
    "F6": {"verdict": "SAFE", "receipt": "moved-to-obsidian"},
    "F7": {"verdict": "SAFE", "receipt": "stale"},
    "F8": {"verdict": "SAFE", "receipt": "stale"},
    "F9": {"verdict": "SAFE", "receipt": "pushed"},
}
JUDGE_KEYS = ("verdict", "verdict_set", "receipt", "receipt_set",
              "forbidden_receipt", "evidence_regex")


def case_id(name):
    m = re.search(r"case-(F\d+)", name)
    return m.group(1) if m else name


def is_judgeable(d):
    return isinstance(d, dict) and any(k in d for k in JUDGE_KEYS)


def expand(path, variables):
    def sub(m):
        return variables.get(m.group(1), m.group(0))
    out = re.sub(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}", sub, path)
    out = re.sub(r"@([A-Za-z_][A-Za-z0-9_]*)@", sub, out)
    return out


def find_basename(root, base, depth=6):
    hits = []
    root = os.path.abspath(root)
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d != ".git"]
        rel = os.path.relpath(dirpath, root)
        if rel != "." and rel.count(os.sep) + 1 > depth:
            dirnames[:] = []
            continue
        if base in filenames:
            hits.append(os.path.join(dirpath, base))
    hits.sort(key=lambda p: (p.count(os.sep), len(p)))
    return hits


def resolve_target(path, variables, bases):
    p = expand(path, variables)
    if os.path.isabs(p) and os.path.exists(p):
        return p, ""
    cands = [p] if os.path.isabs(p) else []
    for b in bases:
        cands.append(os.path.join(b, p))
        cands.append(os.path.join(b, os.path.basename(p)))
    for c in cands:
        if os.path.exists(c):
            return os.path.abspath(c), ""
    hits = []
    for b in bases:
        if os.path.isdir(b):
            hits.extend(find_basename(b, os.path.basename(p)))
    if len(hits) == 1:
        return hits[0], "rebased-by-basename"
    if len(hits) > 1:
        return hits[0], f"rebased-by-basename({len(hits)} hits, took shallowest)"
    return None, "unresolved"


def parse_builder_stdout(text):
    js = None
    stripped = text.strip()
    if stripped.startswith("{"):
        try:
            js = json.loads(stripped.splitlines()[0] if "\n" not in stripped else stripped)
        except Exception:
            js = None
    if js is None:
        for line in text.splitlines():
            line = line.strip()
            if line.startswith("{") and line.endswith("}"):
                try:
                    js = json.loads(line)
                    break
                except Exception:
                    continue
    last_path = ""
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("/") and os.path.exists(line):
            last_path = line
    return js, last_path


def collect_target_specs(meta, stdout_js):
    """Return list of (path_str, judgeable_spec_or_None) from case metadata."""
    out = []

    def add(p, spec=None):
        if isinstance(p, str) and p.strip():
            out.append((p.strip(), spec))

    js = stdout_js or {}
    for key in ("target", "targets", "worktree_paths"):
        v = js.get(key)
        if isinstance(v, str):
            add(v)
        elif isinstance(v, list):
            for item in v:
                add(item if isinstance(item, str) else item.get("path"))

    for key in ("target", "targets"):
        v = meta.get(key)
        if isinstance(v, str):
            add(v)
        elif isinstance(v, list):
            for item in v:
                if isinstance(item, str):
                    add(item)
                elif isinstance(item, dict):
                    add(item.get("path"), item.get("expected") if is_judgeable(item.get("expected")) else None)

    for key in ("expect", "expected"):
        v = meta.get(key)
        if isinstance(v, dict):
            if "path" in v:
                add(v.get("path"), v if is_judgeable(v) else None)
            elif is_judgeable(v):
                pass  # scalar expectation for the single target; merged later
        elif isinstance(v, list):
            for item in v:
                if isinstance(item, dict):
                    add(item.get("path"), item if is_judgeable(item) else None)

    seen, uniq = set(), []
    for p, spec in out:
        if p in seen:
            if spec and not any(s and q == p for q, s in uniq):
                pass
            continue
        seen.add(p)
        uniq.append((p, spec))
    return uniq


def scalar_expectation(meta):
    spec = {}
    for key in ("expect", "expected"):
        v = meta.get(key)
        if is_judgeable(v):
            return {k: v[k] for k in JUDGE_KEYS if k in v}
    for key in JUDGE_KEYS:
        if key in meta:
            spec[key] = meta[key]
    return spec


def entry_expectation(meta, target):
    """Look for a per-path expectation inside expect/expected lists."""
    base = os.path.basename(target)
    for key in ("expect", "expected", "targets"):
        v = meta.get(key)
        items = v if isinstance(v, list) else ([v] if isinstance(v, dict) else [])
        for item in items:
            if not isinstance(item, dict):
                continue
            p = item.get("path") or item.get("target")
            if p and (p == target or os.path.basename(p) == base):
                if is_judgeable(item):
                    return {k: item[k] for k in JUDGE_KEYS if k in item}
                inner = item.get("expected")
                if is_judgeable(inner):
                    return {k: inner[k] for k in JUDGE_KEYS if k in inner}
    return None


def judge_with_spec(spec, status, verdict, receipt, evidence):
    problems = []
    desc = []
    if spec.get("verdict") or spec.get("verdict_set"):
        vs = spec.get("verdict_set") or [spec["verdict"]]
        desc.append("verdict=" + "|".join(vs))
        if status != "found":
            problems.append(f"no verdict line matched ({status})")
        elif verdict not in vs:
            problems.append(f"verdict {verdict!r} not in {vs}")
    rs = spec.get("receipt_set") or ([spec["receipt"]] if spec.get("receipt") else None)
    if rs:
        desc.append("receipt=" + "|".join(rs))
        if status == "found" and receipt not in rs:
            problems.append(f"receipt {receipt!r} not in {rs}")
    if spec.get("forbidden_receipt") and status == "found" and receipt == spec["forbidden_receipt"]:
        problems.append(f"receipt {receipt!r} is forbidden")
    if spec.get("evidence_regex"):
        desc.append("evidence~/" + spec["evidence_regex"] + "/")
        if status == "found" and not re.search(spec["evidence_regex"], evidence):
            problems.append(f"evidence {evidence!r} !~ /{spec['evidence_regex']}/")
    if not problems and status != "found" and not (spec.get("verdict") or spec.get("verdict_set")):
        problems.append("no verdict line matched and spec checks nothing else")
    if problems:
        return "FAIL", " ".join(desc) or "(no spec)", "; ".join(problems)
    return "PASS", " ".join(desc) or "(no spec)", ""


def cmd_shared(args):
    opts = {}
    i = 0
    while i < len(args):
        if args[i].startswith("--"):
            opts[args[i][2:]] = args[i + 1]
            i += 2
        else:
            i += 1
    fixtures, tool = opts["fixtures"], opts["tool"]
    scratch = opts.get("scratch") or "/tmp/souji-runner-shared"
    os.makedirs(scratch, exist_ok=True)
    obs_lines, meta_lines = [], []
    cleanup_roots = []

    def obs(status, case, target, expected, observed, detail):
        obs_lines.append("\t".join([status, case, target, expected, observed,
                                    detail.replace("\t", " ")]))

    def meta(k, v):
        meta_lines.append(f"{k}\t{str(v).replace(chr(9), ' ')}")

    if not os.path.isdir(fixtures):
        obs("NOT-EXERCISED", "shared-fixtures", fixtures, "fixtures dir present", "absent", "")
    else:
        for cname in sorted(os.listdir(fixtures)):
            case_dir = os.path.join(fixtures, cname)
            if not os.path.isdir(case_dir) or not cname.startswith("case-"):
                continue
            cid = case_id(cname)
            exp_path = os.path.join(case_dir, "expected.json")
            meta_src = {}
            if os.path.isfile(exp_path):
                try:
                    meta_src = json.load(open(exp_path))
                except Exception as exc:
                    obs("NOT-EXERCISED", cname, "-", "parsable expected.json",
                        "parse error", str(exc))
                    continue
            elif not any(os.path.isfile(os.path.join(case_dir, b))
                         for b in ("make-fixture.sh", "setup.sh", "build.sh")):
                obs("NOT-EXERCISED", cname, "-", "expected.json present", "absent", "")
                continue

            work = os.path.join(scratch, cname)
            if os.path.isdir(work):
                shutil.rmtree(work)
            shutil.copytree(case_dir, work, symlinks=True, dirs_exist_ok=True)

            builder = next((b for b in ("make-fixture.sh", "setup.sh", "build.sh")
                            if os.path.isfile(os.path.join(work, b))), None)
            stdout_js, last_path = None, ""
            if builder:
                script = os.path.join(work, builder)
                btxt = open(script, errors="replace").read()
                mat_root = os.path.join(scratch, cname + "-root")
                attempts = [(["bash", script], work)]
                if "OUT_DIR" in btxt or os.path.basename(script) != "make-fixture.sh" \
                        or "usage" in btxt.lower():
                    attempts.append((["bash", script, mat_root], work))
                outdir = os.path.join(scratch, cname + "-out")
                cmd3 = ["bash", script]
                if "--force" in btxt:
                    cmd3 += ["--force"]
                if "--out" in btxt:
                    cmd3 += ["--out", outdir]
                    if "--emit-resolved-expected" in btxt:
                        cmd3 += ["--emit-resolved-expected", outdir + ".resolved.json"]
                    if "--inject" in btxt:
                        cmd3 += ["--inject", os.path.join(scratch, cname + "-ledger-inject.txt")]
                    attempts.append((cmd3, work))
                ok = False
                for cmd, cwd in attempts:
                    r = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True,
                                       timeout=180)
                    meta(f"{cname}_builder", " ".join(cmd))
                    meta(f"{cname}_builder_rc", r.returncode)
                    if r.returncode == 0:
                        stdout_js, last_path = parse_builder_stdout(r.stdout)
                        meta(f"{cname}_builder_stdout_head",
                             r.stdout.strip().splitlines()[0][:200] if r.stdout.strip() else "")
                        if r.stderr.strip():
                            meta(f"{cname}_builder_stderr_head",
                                 r.stderr.strip().splitlines()[0][:200])
                        ok = True
                        break
                if not ok:
                    obs("FAIL", cname, "builder", "build rc 0", "all invocations failed",
                        "harness could not materialize the fixture (not a tool verdict)")
                    continue
                # refresh metadata if the builder rewrote expected.json in the copy
                if os.path.isfile(os.path.join(work, "expected.json")):
                    try:
                        fresh = json.load(open(os.path.join(work, "expected.json")))
                        if isinstance(fresh, dict):
                            meta_src = {**meta_src, **fresh}
                    except Exception:
                        pass
                for extra in (outdir + ".resolved.json",):
                    if os.path.isfile(extra):
                        try:
                            meta_src = {**meta_src, **json.load(open(extra))}
                        except Exception:
                            pass

            variables = {"CASE_ROOT": work, "ROOT": work, "FIXTURE_ROOT": work}
            js = stdout_js if isinstance(stdout_js, dict) else {}
            for k in ("case_root", "repo_root", "root", "fixture_root", "target_root"):
                if isinstance(js.get(k), str):
                    variables["CASE_ROOT"] = js[k]
            if last_path and os.path.basename(last_path) not in ("", "."):
                if os.path.isdir(last_path):
                    variables.setdefault("CASE_ROOT", last_path)
            bases = []
            for b in (variables["CASE_ROOT"], work, os.path.join(scratch, cname + "-root"),
                      last_path if os.path.isdir(last_path or "") else None):
                if b and b not in bases and os.path.isdir(b):
                    bases.append(b)

            specs = collect_target_specs(meta_src, js)
            targets = []
            for p, spec in specs:
                resolved, note = resolve_target(p, variables, bases)
                if resolved is None and os.path.isabs(expand(p, variables)):
                    targets.append((expand(p, variables), spec, ""))
                    continue
                targets.append((resolved, spec, note))
            for cand in (variables.get("CASE_ROOT", ""), last_path):
                if cand and os.path.isdir(cand) and (
                        cand.startswith("/tmp/souji-fixture-")
                        or cand.startswith(os.path.abspath(scratch) + os.sep)):
                    cleanup_roots.append(cand)
            if not targets:
                obs("NOT-EXERCISED", cname, "-", "targets resolvable",
                    "no target paths in metadata", "schema not recognized")
                continue

            env = {}
            for k, v in (meta_src.get("env") or {}).items():
                env[k] = expand(str(v), variables)
            stale_days = meta_src.get("stale_days")
            run_targets = [t for t, _, _ in targets if t]
            if not run_targets:
                obs("NOT-EXERCISED", cname, "-", "targets resolvable",
                    "none of the declared paths exist", "")
                continue

            def invoke(extra_env):
                e = dict(os.environ)
                e.update(env)
                e.update(extra_env)
                argv = ["bash", tool]
                if stale_days and int(stale_days) != 1:
                    argv += ["--stale-days", str(stale_days)]
                argv += run_targets
                return subprocess.run(argv, cwd=work, capture_output=True, text=True,
                                      env=e, timeout=600)

            r = invoke({})
            ctext = r.stdout + r.stderr
            judgements = {}
            need_retry = False
            for t, spec, note in targets:
                if not t:
                    continue
                p = None
                for raw in r.stdout.splitlines():
                    q = parse_line(raw)
                    if q and q["path"] and match_path(q["path"], t):
                        p = q
                        break
                sp = (spec or entry_expectation(meta_src, t)
                      or entry_expectation(meta_src, os.path.basename(t))
                      or scalar_expectation(meta_src) or SPEC_FALLBACK.get(cid, {}))
                status = "found" if p else "missing"
                verdict = p["verdict"] if p else ""
                receipt = p["receipt"] if p else ""
                evidence = p["evidence"] if p else ""
                st, desc, det = judge_with_spec(sp, status, verdict, receipt, evidence)
                judgements[t] = (st, desc, det, p, f"env={env or 'default'}")
                if st == "FAIL":
                    need_retry = True
            if need_retry and not env:
                r2 = invoke({"SHOKUNIN_ROOT": variables["CASE_ROOT"]})
                for t, spec, note in targets:
                    if not t or judgements[t][0] != "FAIL":
                        continue
                    p = None
                    for raw in r2.stdout.splitlines():
                        q = parse_line(raw)
                        if q and q["path"] and match_path(q["path"], t):
                            p = q
                            break
                    sp = (spec or entry_expectation(meta_src, t)
                          or scalar_expectation(meta_src) or SPEC_FALLBACK.get(cid, {}))
                    status = "found" if p else "missing"
                    st, desc, det = judge_with_spec(
                        sp, status, p["verdict"] if p else "", p["receipt"] if p else "",
                        p["evidence"] if p else "")
                    judgements[t] = (st, desc, det, p,
                                     f"env=SHOKUNIN_ROOT={variables['CASE_ROOT']}")
                ctext += r2.stdout + r2.stderr
            exp_rc = None
            if isinstance(meta_src.get("run_exit_code"), int):
                exp_rc = meta_src["run_exit_code"]
            elif isinstance(meta_src.get("expected"), dict):
                ec = meta_src["expected"].get("exit_code")
                if isinstance(ec, dict):
                    exp_rc = ec.get("expected")
                elif isinstance(ec, int):
                    exp_rc = ec
            meta(f"{cname}_exit_rc", r.returncode)
            if exp_rc is not None:
                ok = r.returncode == exp_rc or r.returncode in \
                    (meta_src.get("expected", {}).get("exit_code", {}) or {}).get("tolerated", [])
                obs("PASS" if ok else "FAIL", cname, "run-exit", f"exit {exp_rc}",
                    f"exit {r.returncode}", "tolerated set honored" if ok else "")
            for t, spec, note in targets:
                if not t:
                    obs("NOT-EXERCISED", cname, spec or "-", "target resolvable",
                        "unresolved", note)
                    continue
                st, desc, det, p, envdesc = judgements[t]
                obs(st, cname, t, desc,
                    (f"{p['verdict']}/{p['receipt']}" if p else "<no line>"),
                    (det + " " + note + f" [{envdesc}]").strip())
            for canary in (meta_src.get("leak_canaries") or {}).values():
                if not isinstance(canary, str):
                    continue
                if canary in ctext:
                    obs("FAIL", cname, "canary", "no leak of canary token", "LEAKED",
                        "token found in tool output")
                else:
                    obs("PASS", cname, "canary", "no leak of canary token", "absent",
                        canary[:14] + "...")

    for root in cleanup_roots:
        shutil.rmtree(root, ignore_errors=True)
    with open(opts["obs"], "a") as fh:
        for line in obs_lines:
            fh.write(line + "\n")
    with open(opts["meta"], "a") as fh:
        for line in meta_lines:
            fh.write(line + "\n")


def _tool_supports(tool_path, token):
    try:
        return token in open(tool_path, errors="replace").read()
    except OSError:
        return False


def _run_tool(tool, cwd, targets, env, stale_days=None):
    e = dict(os.environ)
    e.update(env)
    argv = ["bash", tool]
    if stale_days and int(stale_days) != 1:
        argv += ["--stale-days", str(stale_days)]
    argv += targets
    return subprocess.run(argv, cwd=cwd, capture_output=True, text=True, env=e,
                          timeout=600)


def _line_for(stdout, target):
    hits = []
    for raw in stdout.splitlines():
        p = parse_line(raw)
        if p and p.get("path") and match_path(p["path"], target):
            hits.append(p)
    if not hits:
        return None
    exact = [h for h in hits if h["path"] == target
             or os.path.normpath(h["path"]) == os.path.normpath(target)]
    return exact[0] if exact else hits[0]


def _entry_spec(meta_src, target, phase):
    base = os.path.basename(target)
    for key in ("targets", "expect", "expected"):
        v = meta_src.get(key)
        items = v if isinstance(v, list) else ([v] if isinstance(v, dict) else [])
        for item in items:
            if not isinstance(item, dict):
                continue
            p = item.get("path") or item.get("target")
            if not p or not (p == target or os.path.basename(p) == base):
                continue
            if phase == "armed" and is_judgeable(item.get("expected_when_armed")):
                return item["expected_when_armed"]
            if phase == "disarmed" and is_judgeable(item.get("expected_when_disarmed")):
                return item["expected_when_disarmed"]
            if is_judgeable(item):
                return item
            if is_judgeable(item.get("expected")):
                return item["expected"]
    return None


def _spec_for(meta_src, target, cid, phase):
    return (_entry_spec(meta_src, target, phase)
            or scalar_expectation(meta_src)
            or SPEC_FALLBACK.get(cid, {}))


def _armed_ledger(meta_src, variables, scratch, cname):
    cols = meta_src.get("ledger_columns") or [
        "source_path", "source_sha256", "vault_path", "vault_sha256",
        "exported_at", "note"]
    rows = meta_src.get("declared_ledger_rows") or []
    lines = ["\t".join(cols)]
    for row in rows:
        if not isinstance(row, dict):
            continue
        vals = [expand(str(row.get(c, "")), variables) for c in cols]
        if any(vals):
            lines.append("\t".join(vals))
    if len(lines) == 1:
        return None
    path = os.path.join(scratch, cname + "-armed-ledger.tsv")
    with open(path, "w") as fh:
        fh.write("\n".join(lines) + "\n")
    return path


def cmd_shared_v2(args):
    """Tolerant shared-fixture suite: heterogeneous per-seat schemas."""
    opts = {}
    i = 0
    while i < len(args):
        if args[i].startswith("--"):
            opts[args[i][2:]] = args[i + 1]
            i += 2
        else:
            i += 1
    fixtures, tool = opts["fixtures"], opts["tool"]
    scratch = opts.get("scratch") or "/tmp/souji-runner-shared"
    os.makedirs(scratch, exist_ok=True)
    obs_lines, meta_lines, cleanup_roots = [], [], []

    def obs(status, case, target, expected, observed, detail):
        obs_lines.append("\t".join([status, case, target, expected,
                                    observed, detail.replace("\t", " ")]))

    def meta(k, v):
        meta_lines.append(f"{k}\t{str(v).replace(chr(9), ' ')}")

    ledger_seam = _tool_supports(tool, "SOUJI_LEDGER")
    if not os.path.isdir(fixtures):
        obs("NOT-EXERCISED", "shared-fixtures", fixtures, "fixtures dir present",
            "absent", "")
    else:
        for cname in sorted(os.listdir(fixtures)):
            case_dir = os.path.join(fixtures, cname)
            if not os.path.isdir(case_dir) or not cname.startswith("case-"):
                continue
            cid = case_id(cname)
            exp_path = os.path.join(case_dir, "expected.json")
            meta_src = {}
            if os.path.isfile(exp_path):
                try:
                    meta_src = json.load(open(exp_path))
                except Exception as exc:
                    obs("NOT-EXERCISED", cname, "-", "parsable expected.json",
                        "parse error", str(exc))
                    continue
            builders = [b for b in ("make-fixture.sh", "setup.sh", "build.sh")
                        if os.path.isfile(os.path.join(case_dir, b))]
            if not meta_src and not builders:
                obs("NOT-EXERCISED", cname, "-", "expected.json present",
                    "absent", "")
                continue

            work = os.path.join(scratch, cname)
            if os.path.isdir(work):
                shutil.rmtree(work)
            shutil.copytree(case_dir, work, symlinks=True, dirs_exist_ok=True)

            stdout_js, last_path = None, ""
            if builders:
                script = os.path.join(work, builders[0])
                btxt = open(script, errors="replace").read()
                mat_root = os.path.join(scratch, cname + "-root")
                outdir = os.path.join(scratch, cname + "-out")
                attempts = []
                if "--out" in btxt:
                    cmd = ["bash", script, "--out", outdir]
                    if "--emit-resolved-expected" in btxt:
                        cmd += ["--emit-resolved-expected", outdir + ".resolved.json"]
                    if "--inject" in btxt:
                        cmd += ["--inject", os.path.join(scratch, cname + "-inject.txt")]
                    attempts.append((cmd, work))
                attempts.append((["bash", script], work))
                attempts.append((["bash", script, mat_root], work))
                ok = False
                for cmd, cwd in attempts:
                    r = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True,
                                       timeout=180)
                    meta(f"{cname}_builder", " ".join(cmd))
                    meta(f"{cname}_builder_rc", r.returncode)
                    if r.returncode == 0:
                        stdout_js, last_path = parse_builder_stdout(r.stdout)
                        if r.stderr.strip():
                            meta(f"{cname}_builder_stderr_head",
                                 r.stderr.strip().splitlines()[0][:200])
                        ok = True
                        break
                if not ok:
                    obs("FAIL", cname, "builder", "build rc 0",
                        "all invocations failed",
                        "harness could not materialize the fixture (not a tool verdict)")
                    continue
                if os.path.isfile(os.path.join(work, "expected.json")):
                    try:
                        fresh = json.load(open(os.path.join(work, "expected.json")))
                        if isinstance(fresh, dict):
                            meta_src = {**meta_src, **fresh}
                    except Exception:
                        pass
                for extra in (outdir + ".resolved.json",):
                    if os.path.isfile(extra):
                        try:
                            meta_src = {**meta_src, **json.load(open(extra))}
                        except Exception:
                            pass
                if isinstance(stdout_js, dict):
                    for k in ("expected", "env", "target", "targets",
                              "worktree_paths", "case_root", "repo_root"):
                        if k in stdout_js and k not in meta_src:
                            meta_src[k] = stdout_js[k]

            variables = {"CASE_ROOT": work, "ROOT": work, "FIXTURE_ROOT": work}
            js = stdout_js if isinstance(stdout_js, dict) else {}
            for k in ("case_root", "repo_root", "root", "fixture_root",
                      "target_root"):
                if isinstance(js.get(k), str):
                    variables["CASE_ROOT"] = variables["FIXTURE_ROOT"] = js[k]
            if last_path and os.path.isdir(last_path):
                variables["CASE_ROOT"] = variables["FIXTURE_ROOT"] = last_path
            mat_root = os.path.join(scratch, cname + "-root")
            bases = []
            for b in (variables["CASE_ROOT"], work, mat_root,
                      last_path if os.path.isdir(last_path or "") else None):
                if b and b not in bases and os.path.isdir(b):
                    bases.append(b)

            specs = collect_target_specs(meta_src, js)
            if not specs and last_path and os.path.exists(last_path):
                specs = [(last_path, None)]
            targets = []
            for p, spec in specs:
                resolved, note = resolve_target(p, variables, bases)
                targets.append((resolved or expand(p, variables), spec, note))
            for cand in (variables.get("CASE_ROOT", ""), last_path):
                if cand and os.path.isdir(cand) and (
                        cand.startswith("/tmp/souji-fixture-")
                        or cand.startswith(os.path.abspath(scratch) + os.sep)):
                    cleanup_roots.append(cand)
            if not targets:
                obs("NOT-EXERCISED", cname, "-", "targets resolvable",
                    "no target paths in metadata", "schema not recognized")
                continue
            run_targets = [t for t, _, _ in targets
                           if t and (os.path.exists(t) or os.path.isabs(t))]
            if not run_targets:
                obs("NOT-EXERCISED", cname, "-", "targets resolvable",
                    "none of the declared paths exist", "")
                continue

            env = {k: expand(str(v), variables)
                   for k, v in (meta_src.get("env") or {}).items()}
            stale_days = meta_src.get("stale_days")
            tlist = meta_src.get("targets")
            phase_arm = bool(meta_src.get("declared_ledger_rows"))
            if not phase_arm and isinstance(tlist, list):
                phase_arm = any(
                    isinstance(x, dict) and is_judgeable(x.get("expected_when_armed"))
                    for x in tlist)
            ctext = ""
            runs = []  # (phase, result)
            if phase_arm:
                ledger = _armed_ledger(meta_src, variables, scratch, cname)
                env_armed = dict(env)
                if ledger and ledger_seam:
                    env_armed["SOUJI_LEDGER"] = ledger
                elif ledger:
                    lr = os.path.join(scratch, "lane", "corpus", "knowledge")
                    os.makedirs(lr, exist_ok=True)
                    shutil.copyfile(ledger, os.path.join(lr, "obsidian-ledger.tsv"))
                    env_armed["SOUJI_LEDGER"] = os.path.join(lr, "obsidian-ledger.tsv")
                rA = _run_tool(tool, work, run_targets, env_armed, stale_days)
                runs.append(("armed", rA))
                rD = _run_tool(tool, work, run_targets, env, stale_days)
                runs.append(("disarmed", rD))
                ctext = rA.stdout + rA.stderr + rD.stdout + rD.stderr
            else:
                r = _run_tool(tool, work, run_targets, env, stale_days)
                runs.append(("default", r))
                if not env:
                    probe = []
                    for t in run_targets:
                        p = _line_for(r.stdout, t)
                        sp = _spec_for(meta_src, t, cid, "default")
                        st = judge_with_spec(
                            sp, "found" if p else "missing",
                            p["verdict"] if p else "", p["receipt"] if p else "",
                            p["evidence"] if p else "")[0]
                        probe.append(st)
                    if "FAIL" in probe:
                        r2 = _run_tool(tool, work, run_targets,
                                       {"SHOKUNIN_ROOT": variables["CASE_ROOT"]},
                                       stale_days)
                        runs.append(("SHOKUNIN_ROOT=case", r2))
                        ctext += r2.stdout + r2.stderr
                ctext += r.stdout + r.stderr

            exp_rc = None
            if isinstance(meta_src.get("run_exit_code"), int):
                exp_rc = meta_src["run_exit_code"]
            elif isinstance(meta_src.get("expected"), dict):
                ec = meta_src["expected"].get("exit_code")
                if isinstance(ec, dict):
                    exp_rc = ec.get("expected")
                elif isinstance(ec, int):
                    exp_rc = ec
            tolerated = []
            if isinstance(meta_src.get("expected"), dict):
                ec = meta_src["expected"].get("exit_code")
                if isinstance(ec, dict):
                    tolerated = ec.get("tolerated") or []
            for phase, res in runs:
                meta(f"{cname}_{phase}_rc", res.returncode)
                if exp_rc is not None and phase != "SHOKUNIN_ROOT=case":
                    ok = res.returncode == exp_rc or res.returncode in tolerated
                    obs("PASS" if ok else "FAIL", cname, f"run-exit[{phase}]",
                        f"exit {exp_rc}", f"exit {res.returncode}",
                        "tolerated set honored" if ok else "")

            for t, spec, note in targets:
                if not t:
                    obs("NOT-EXERCISED", cname, spec or "-", "target resolvable",
                        "unresolved", note)
                    continue
                for phase, res in runs:
                    p = _line_for(res.stdout if phase != "SHOKUNIN_ROOT=case"
                                  else res.stdout, t)
                    sp = _spec_for(meta_src, t, cid, phase)
                    st, desc, det = judge_with_spec(
                        sp, "found" if p else "missing",
                        p["verdict"] if p else "", p["receipt"] if p else "",
                        p["evidence"] if p else "")
                    if phase == "SHOKUNIN_ROOT=case" and st == "PASS":
                        continue  # retry only rescues, it does not add rows
                    obs(st, cname, t if phase == "default" else f"{t}[{phase}]",
                        desc, (f"{p['verdict']}/{p['receipt']}" if p else "<no line>"),
                        (det + " " + note + f" [{phase}]").strip())

            for canary in (meta_src.get("leak_canaries") or {}).values():
                if not isinstance(canary, str):
                    continue
                if canary in ctext:
                    obs("FAIL", cname, "canary", "no leak of canary token",
                        "LEAKED", "token found in tool output")
                else:
                    obs("PASS", cname, "canary", "no leak of canary token",
                        "absent", canary[:14] + "...")

    for root in cleanup_roots:
        shutil.rmtree(root, ignore_errors=True)
    with open(opts["obs"], "a") as fh:
        for line in obs_lines:
            fh.write(line + "\n")
    with open(opts["meta"], "a") as fh:
        for line in meta_lines:
            fh.write(line + "\n")


def cmd_report(args):
    opts = {}
    i = 0
    while i < len(args):
        if args[i].startswith("--"):
            opts[args[i][2:]] = args[i + 1]
            i += 2
        else:
            i += 1

    meta = {}
    for row in read_lines(opts.get("meta", "")):
        if "\t" in row:
            k, v = row.split("\t", 1)
            meta.setdefault(k, v)

    rows = []
    for row in read_lines(opts.get("obs", "")):
        if not row.strip():
            continue
        f = row.split("\t")
        while len(f) < 6:
            f.append("")
        rows.append({"status": f[0], "case": f[1], "target": f[2],
                     "expected": f[3], "observed": f[4], "detail": f[5]})

    counts = {"checks": len(rows), "pass": 0, "fail": 0, "not_exercised": 0,
              "info": 0, "tool_absent": 0}
    for r in rows:
        s = r["status"].lower()
        if r["status"] == "TOOL-ABSENT":
            counts["tool_absent"] += 1
        elif s == "pass":
            counts["pass"] += 1
        elif s == "fail":
            counts["fail"] += 1
        elif s == "not-exercised":
            counts["not_exercised"] += 1
        else:
            counts["info"] += 1

    def suite_of(case):
        if case == "selftest":
            return "selftest"
        if case == "cli":
            return "cli"
        if case.startswith("case-"):
            return "shared-fixtures"
        if case == "live":
            return "live"
        return "independent"

    suites = {}
    for r in rows:
        suites.setdefault(suite_of(r["case"]), []).append(r)

    def read_cap(path, cap=200000):
        try:
            with open(path, "r", errors="replace") as fh:
                return fh.read()[:cap]
        except OSError:
            return ""

    doc = {
        "runner": "S19",
        "round": 2,
        "generated_utc": datetime.datetime.now(datetime.timezone.utc)
        .strftime("%Y-%m-%dT%H:%M:%SZ"),
        "verdict": opts.get("verdict", "FAIL"),
        "tool": {
            "path": meta.get("tool_path", ""),
            "present": meta.get("tool_present", "0") == "1",
            "sha256": meta.get("tool_sha256", ""),
            "bytes": meta.get("tool_bytes", ""),
            "mtime_utc": meta.get("tool_mtime_utc", ""),
        },
        "environment": {
            "lane": meta.get("lane", ""),
            "fleet_root": meta.get("fleet_root", ""),
            "fixtures_dir": meta.get("fixtures_dir", ""),
            "bash": meta.get("bash_version", ""),
            "git": meta.get("git_version", ""),
            "rg": meta.get("rg_path", "") + " " + meta.get("rg_version", ""),
            "python3": meta.get("python3_version", ""),
            "host": meta.get("runner_host", ""),
            "started_utc": meta.get("started_utc", ""),
        },
        "measurements": {k: v for k, v in meta.items()
                         if k not in ("tool_path", "tool_sha256", "tool_bytes",
                                      "tool_mtime_utc", "tool_present", "lane",
                                      "fleet_root", "fixtures_dir", "bash_version",
                                      "git_version", "rg_path", "rg_version",
                                      "python3_version", "runner_host", "started_utc")},
        "summary": counts,
        "suites": [{"suite": k, "checks": v} for k, v in sorted(suites.items())],
        "harness": {
            "note": "extracted copies of the exact harness that produced this file; "
                    "re-run: write both files to a dir and run bash harness.sh",
            "sha256_meta": meta.get("harness_sha256", ""),
            "sh": read_cap(opts.get("harness-sh", "")),
            "py": read_cap(opts.get("harness-py", "")),
        },
    }
    out = opts.get("out")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with open(out, "w") as fh:
        json.dump(doc, fh, indent=2)
        fh.write("\n")


def main():
    cmd = sys.argv[1]
    fn = {
        "line": cmd_line, "targets": cmd_targets, "exitcode": cmd_exitcode,
        "canaries": cmd_canaries, "judge": cmd_judge, "verdict": cmd_verdict,
        "report": cmd_report, "shared": cmd_shared_v2,
    }[cmd]
    fn(sys.argv[2:])


if __name__ == "__main__":
